// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr) public {
        vm.assume(addr != address(0));
        vm.assume(addr != address(c));
        // Initialize the market so the contract is active
        if (c.marketDrugs() == 0) {
            c.seedMarket{value: 1 ether}(1000);
        }
        // Ensure the address has zero Kilos before calling getFreeKilo
        if (c.Kilos(addr) != 0) {
            // If not zero, we can't test the invariant; skip
            vm.assume(false);
        }
        // Call getFreeKilo as a different user (the contract doesn't care about msg.sender)
        vm.prank(addr);
        c.getFreeKilo();
        // The invariant: after getFreeKilo for an address with zero Kilos, Kilos should equal STARTING_KILOS (300)
        assertTrue(c.Kilos(addr) == 300);
    }
}

